add_filter( 'woocommerce_account_menu_items', 'perfectpixel_reorder_account_tabs', 50 );

function perfectpixel_reorder_account_tabs( $items ) {
	$ordered = array();
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{account_tabs_order}}' ) ) ) as $key ) {
		if ( isset( $items[ $key ] ) && 'customer-logout' !== $key ) {
			$ordered[ $key ] = $items[ $key ];
		}
	}
	$logout = isset( $items['customer-logout'] ) ? array( 'customer-logout' => $items['customer-logout'] ) : array();
	return $ordered + array_diff_key( $items, $ordered, $logout ) + $logout;
}
